# owner: platform
from hourglass.models import Shift


def _check(shifts: list[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")


def _totals(shifts: list[Shift]) -> dict:
    totals = {}
    for shift in shifts:
        count, mins = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (
            count + 1, mins + shift.span.minutes
        )
    return totals


# ---
def timesheet_lines(shifts: list[Shift]) -> list[str]:
    """One line per worker, busiest first."""
    _check(shifts)
    totals = _totals(shifts)
    order = sorted(
        totals, key=lambda w: (-totals[w][1], w)
    )
    return [_line(w, *totals[w]) for w in order]


def _line(worker: str, count: int, mins: int) -> str:
    hours = mins / 60
    return f"{worker}: {count} shifts, {hours:.1f} hours"

